1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
22	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
23	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
24	    @Mapping(target = "locality", expression = "java(org.springframework.samples.petclinic.util.CustomerCode.region(owner.getCustomerCode()))")
25	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
26	    @Mapping(target = "checkDigit", expression = "java(org.springframework.samples.petclinic.util.LuhnCheckDigit.of(owner.getCustomerCode()))")
27	    @Mapping(target = "membershipNumber", expression = "java(owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
28	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
29	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
30	    @Mapping(target = "contactPreference", expression = "java((owner.getEmail() != null && !owner.getEmail().isBlank()) ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE)")
31	    @Mapping(target = "identityKey", expression = "java(org.springframework.samples.petclinic.util.OwnerIdentity.identityKey(owner))")
32	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
33	    @Mapping(target = "telephoneDisplay", expression = "java(org.springframework.samples.petclinic.util.TelephoneNormalizer.toDisplay(owner.getTelephone()))")
34	    OwnerDto toOwnerDto(Owner owner);
35	
36	    /**
37	     * Derives the owner's IANA {@code timezone} from its locality (region) via a fixed
38	     * region-to-timezone table: {@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne}
39	     * and {@code QLD -> Australia/Brisbane}. Returns {@code null} for a region not in the table.
40	     */
41	    default String timezone(Owner owner) {
42	        String region = org.springframework.samples.petclinic.util.CustomerCode.region(owner.getCustomerCode());
43	        if (region == null) {
44	            return null;
45	        }
46	        return switch (region) {
47	            case "NSW" -> "Australia/Sydney";
48	            case "VIC" -> "Australia/Melbourne";
49	            case "QLD" -> "Australia/Brisbane";
50	            default -> null;
51	        };
52	    }
53	
54	    /**
55	     * Derives the owner's {@code ageBand} from its {@code birthDate}, measured against its
56	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64 and
57	     * {@code SENIOR} at 65 or older. Returns {@code null} when no birth date is present.
58	     */
59	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
60	        java.time.LocalDate birthDate = owner.getBirthDate();
61	        java.time.LocalDate asOf = owner.getRegistrationDate();
62	        if (birthDate == null || asOf == null) {
63	            return null;
64	        }
65	        int years = java.time.Period.between(birthDate, asOf).getYears();
66	        if (years < 18) {
67	            return OwnerDto.AgeBandEnum.MINOR;
68	        }
69	        if (years < 65) {
70	            return OwnerDto.AgeBandEnum.ADULT;
71	        }
72	        return OwnerDto.AgeBandEnum.SENIOR;
73	    }
74	
75	    /**
76	     * Computes the owner's {@code membershipPoints}. Starts at 0; adds 2 when a non-blank email is
77	     * present; adds 1 when {@code namesakeCount} is 0; adds 2 for a household of 3 or more; adds 3
78	     * when tenure exceeds 365 days (measured from {@code registrationDate} to today).
79	     */
80	    default int membershipPoints(Owner owner) {
81	        int points = 0;
82	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
83	            points += 2;
84	        }
85	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
86	            points += 1;
87	        }
88	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
89	            points += 2;
90	        }
91	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
92	        if (registrationDate != null
93	                && java.time.temporal.ChronoUnit.DAYS.between(registrationDate, java.time.LocalDate.now()) > 365) {
94	            points += 3;
95	        }
96	        return points;
97	    }
98	
99	    /**
100	     * Derives the owner's {@code membershipLevel} from {@code membershipPoints}: 1 for 0-1 points,
101	     * 2 for 2-3 points, 3 for 4-5 points and 4 for 6 or more points.
102	     */
103	    default int membershipLevel(Owner owner) {
104	        int points = membershipPoints(owner);
105	        if (points <= 1) {
106	            return 1;
107	        }
108	        if (points <= 3) {
109	            return 2;
110	        }
111	        if (points <= 5) {
112	            return 3;
113	        }
114	        return 4;
115	    }
116	
117	    /**
