119	     * {@code title + ' ' + lastName} when a non-blank title is present, or just the {@code lastName}
120	     * when no title is given.
121	     */
122	    default String salutation(Owner owner) {
123	        String title = owner.getTitle();
124	        if (title == null || title.isBlank()) {
125	            return owner.getLastName();
126	        }
127	        return title + " " + owner.getLastName();
128	    }
